import json,sys,hashlib
from pathlib import Path
from mcp.server.fastmcp import FastMCP
from mcp.types import ToolAnnotations
root=Path(__file__).parent
candidate=json.loads((root/'candidate.json').read_text())
mcp=FastMCP('field-probe')
@mcp.tool(annotations=ToolAnnotations(readOnlyHint=True,destructiveHint=False,idempotentHint=True,openWorldHint=False))
def read_candidate_field(pointer:str)->dict[str,object]:
    value=candidate
    if pointer:
        if not pointer.startswith('/'):
            raise ValueError('JSON Pointer must start with /')
        for token in pointer[1:].split('/'):
            key=token.replace('~1','/').replace('~0','~')
            value=value[int(key)] if isinstance(value,list) else value[key]
    typ='null' if value is None else 'boolean' if isinstance(value,bool) else 'string' if isinstance(value,str) else 'number' if isinstance(value,(int,float)) else 'array' if isinstance(value,list) else 'object'
    result={'pointer':pointer,'json_type':typ,'literal':json.dumps(value,ensure_ascii=False,separators=(',',':'))}
    with (root/'calls.jsonl').open('a') as f:f.write(json.dumps(result,ensure_ascii=False)+'\n')
    return result
if __name__=='__main__':mcp.run(transport='stdio')
